namespace Umbraco.Bench.Umbraco.Models.Blocks;

using Microsoft.AspNetCore.Html;

/// <summary>Plain view model for the hero block.</summary>
public sealed class HeroModel
{
    public string Heading { get; init; } = string.Empty;

    public string Subheading { get; init; } = string.Empty;

    public string? ImageUrl { get; init; }
}

/// <summary>Plain view model for the rich text block.</summary>
public sealed class RichTextModel
{
    public IHtmlContent Text { get; init; } = new HtmlString(string.Empty);
}

/// <summary>Plain view model for the image block.</summary>
public sealed class ImageBlockModel
{
    public string? ImageUrl { get; init; }

    public string Caption { get; init; } = string.Empty;

    public string AltText { get; init; } = string.Empty;
}

/// <summary>Plain view model for the quote block.</summary>
public sealed class QuoteModel
{
    public string Quote { get; init; } = string.Empty;

    public string Attribution { get; init; } = string.Empty;
}

/// <summary>One entry in a post list.</summary>
public sealed class PostListItem
{
    public string Title { get; init; } = string.Empty;

    public string Url { get; init; } = string.Empty;

    public string Excerpt { get; init; } = string.Empty;

    public string? PostDate { get; init; }
}

/// <summary>Plain view model for the post list block.</summary>
public sealed class PostListBlockModel
{
    public string Heading { get; init; } = string.Empty;

    public IReadOnlyList<PostListItem> Posts { get; init; } = Array.Empty<PostListItem>();
}

