@using Umbraco.Bench.Umbraco.Models.Blocks
@model PostListBlockModel

<div class="max-w-3xl mx-auto px-6 py-10">
    @if (!string.IsNullOrEmpty(Model.Heading))
    {
        <h2 class="text-2xl font-bold text-slate-900 mb-6">@Model.Heading</h2>
    }
    <div class="space-y-6">
        @foreach (var post in Model.Posts)
        {
            <article class="bg-white rounded-lg shadow-sm border border-slate-200 p-6 hover:shadow-md transition-shadow">
                <h3 class="text-lg font-semibold">
                    <a href="@post.Url" class="text-sky-700 hover:underline">@post.Title</a>
                </h3>
                @if (!string.IsNullOrEmpty(post.PostDate))
                {
                    <p class="text-sm text-slate-500 mt-1">@post.PostDate</p>
                }
                @if (!string.IsNullOrEmpty(post.Excerpt))
                {
                    <p class="mt-2 text-slate-700">@post.Excerpt</p>
                }
            </article>
        }
    </div>
</div>

