@using Umbraco.Extensions
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<PostListBlock>>
@{
    var site = Umbraco.AssignedContentItem.AncestorOrSelf<BlogSite>();
    var posts = (site?.Children<BlogPost>() ?? Enumerable.Empty<BlogPost>())
        .OrderByDescending(p => p.PostDate)
        .Select(p => new Umbraco.Bench.Umbraco.Models.Blocks.PostListItem
        {
            Title = p.Name(),
            Url = p.Url(),
            Excerpt = p.Excerpt ?? "",
            PostDate = p.PostDate?.ToString("MMMM d, yyyy"),
        })
        .ToList();
    var model = new Umbraco.Bench.Umbraco.Models.Blocks.PostListBlockModel
    {
        Heading = Model.Content.Heading ?? "",
        Posts = posts,
    };
}
@await Component.InvokeAsync("PostList", new { model })

