namespace Umbraco.Bench.Umbraco.Models.Blocks;

using Microsoft.AspNetCore.Html;

/// <summary>Plain view model for the hero block.</summary>
public sealed class HeroModel
{
    public string Heading { get; init; } = string.Empty;

    public string Subheading { get; init; } = string.Empty;

    public string? ImageUrl { get; init; }
}

/// <summary>Plain view model for the rich text block.</summary>
public sealed class RichTextModel
{
    public IHtmlContent Text { get; init; } = new HtmlString(string.Empty);
}

/// <summary>Plain view model for the image block.</summary>
public sealed class ImageBlockModel
{
    public string? ImageUrl { get; init; }

    public string Caption { get; init; } = string.Empty;

    public string AltText { get; init; } = string.Empty;
}

/// <summary>Plain view model for the quote block.</summary>
public sealed class QuoteModel
{
    public string Quote { get; init; } = string.Empty;

    public string Attribution { get; init; } = string.Empty;
}

/// <summary>One entry in a post list.</summary>
public sealed class PostListItem
{
    public string Title { get; init; } = string.Empty;

    public string Url { get; init; } = string.Empty;

    public string Excerpt { get; init; } = string.Empty;

    public string? PostDate { get; init; }
}

/// <summary>Plain view model for the post list block.</summary>
public sealed class PostListBlockModel
{
    public string Heading { get; init; } = string.Empty;

    public IReadOnlyList<PostListItem> Posts { get; init; } = Array.Empty<PostListItem>();
}

@using Umbraco.Extensions
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<HeroBlock>>
@{
    var model = new Umbraco.Bench.Umbraco.Models.Blocks.HeroModel
    {
        Heading = Model.Content.Heading ?? "",
        Subheading = Model.Content.Subheading ?? "",
        ImageUrl = Model.Content.Image?.GetCropUrl(width: 1600),
    };
}
@await Component.InvokeAsync("Hero", new { model })

@using Umbraco.Extensions
@using Umbraco.Cms.Core.Strings
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<RichTextBlock>>
@{
    var markup = Model.Content.Text switch
    {
        IHtmlEncodedString encoded => encoded.ToHtmlString() ?? string.Empty,
        string plain => plain,
        null => string.Empty,
        _ => Model.Content.Text?.ToString() ?? string.Empty,
    };
    var model = new Umbraco.Bench.Umbraco.Models.Blocks.RichTextModel
    {
        Text = new Microsoft.AspNetCore.Html.HtmlString(markup),
    };
}
@await Component.InvokeAsync("RichText", new { model })

@using Umbraco.Extensions
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<ImageBlock>>
@{
    var model = new Umbraco.Bench.Umbraco.Models.Blocks.ImageBlockModel
    {
        ImageUrl = Model.Content.Image?.GetCropUrl(width: 1200),
        Caption = Model.Content.Caption ?? "",
        AltText = Model.Content.AltText ?? "",
    };
}
@await Component.InvokeAsync("ImageBlock", new { model })

@using Umbraco.Extensions
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<QuoteBlock>>
@{
    var model = new Umbraco.Bench.Umbraco.Models.Blocks.QuoteModel
    {
        Quote = Model.Content.Quote ?? "",
        Attribution = Model.Content.Attribution ?? "",
    };
}
@await Component.InvokeAsync("Quote", new { model })

@using Umbraco.Extensions
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<PostListBlock>>
@{
    var site = Umbraco.AssignedContentItem.AncestorOrSelf<BlogSite>();
    var posts = (site?.Children<BlogPost>() ?? Enumerable.Empty<BlogPost>())
        .OrderByDescending(p => p.PostDate)
        .Select(p => new Umbraco.Bench.Umbraco.Models.Blocks.PostListItem
        {
            Title = p.Name(),
            Url = p.Url(),
            Excerpt = p.Excerpt ?? "",
            PostDate = p.PostDate?.ToString("MMMM d, yyyy"),
        })
        .ToList();
    var model = new Umbraco.Bench.Umbraco.Models.Blocks.PostListBlockModel
    {
        Heading = Model.Content.Heading ?? "",
        Posts = posts,
    };
}
@await Component.InvokeAsync("PostList", new { model })

